import"./chunk-VC46IEJQ.js";var e=(n,o,s,r,a)=>({name:n,desc:o,tour:s,source:r,...a?{spoiler:a}:{}}),t={id:"braavos",intro:{en:"The Secret City: a lagoon city of about a hundred islands laced with canals and bridges, entered between the legs of the Titan, a fortress shaped like a colossal warrior. Its fleets, trade and the Iron Bank make it one of the great powers of Essos.",zh:"\u201C\u79D8\u5BC6\u4E4B\u57CE\u201D\u5E03\u62C9\u4F5B\u65AF\u5750\u843D\u5728\u6F5F\u6E56\u4E4B\u4E2D\uFF0C\u7EA6\u767E\u5EA7\u5C9B\u5C7F\u7531\u8FD0\u6CB3\u4E0E\u6865\u6881\u4E32\u8054\u3002\u8239\u53EA\u987B\u4ECE\u5E03\u62C9\u4F5B\u65AF\u6CF0\u5766\u80EF\u4E0B\u9A76\u5165\u2014\u2014\u90A3\u662F\u4E00\u5EA7\u5DE8\u4EBA\u6218\u58EB\u6A21\u6837\u7684\u8981\u585E\u3002\u8230\u961F\u3001\u5546\u8D38\u4E0E\u94C1\u91D1\u5E93\uFF0C\u4F7F\u5B83\u8DFB\u8EAB\u5384\u7D22\u65AF\u5F3A\u6743\u4E4B\u5217\u3002"},notes:{en:"From the novels (mainly A Feast for Crows): a lagoon of many islands, canals, the Titan with fires in its eyes, the Arsenal, Chequy Port, Purple Harbor, Ragman's Harbor, the Sealord, the Iron Bank, the House of Black and White, the Isle of the Gods and the Drowned Town. Harbour positions come from wiki summaries. Invented here: the island plan, every building's appearance, the Titan's pose and size, and all colours.",zh:"\u51FA\u81EA\u5C0F\u8BF4\uFF08\u4E3B\u8981\u662F\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\uFF09\uFF1A\u591A\u5C9B\u6F5F\u6E56\u4E0E\u8FD0\u6CB3\u3001\u53CC\u773C\u71C3\u706B\u7684\u5E03\u62C9\u4F5B\u65AF\u6CF0\u5766\u3001\u5175\u5DE5\u5382\u3001\u65B9\u683C\u6E2F\u3001\u7D2B\u6E2F\u3001\u62C9\u683C\u66FC\u6E2F\u3001\u6D77\u738B\u3001\u94C1\u91D1\u5E93\u3001\u9ED1\u767D\u4E4B\u9662\u3001\u4F17\u795E\u4E4B\u5C9B\u4E0E\u6C89\u6CA1\u9547\u3002\u5404\u6E2F\u53E3\u7684\u65B9\u4F4D\u53D6\u81EA\u7EF4\u57FA\u6458\u8981\u3002\u672C\u573A\u666F\u81EA\u62DF\uFF1A\u5C9B\u5C7F\u5E03\u5C40\u3001\u6240\u6709\u5EFA\u7B51\u5916\u89C2\u3001\u6CF0\u5766\u7684\u59FF\u6001\u4E0E\u5C3A\u5BF8\uFF0C\u4EE5\u53CA\u5168\u90E8\u914D\u8272\u3002"},tour:["seaward-isles","titan","arsenal","chequy-port","canals-and-bridges","ragmans-harbor","house-black-white","isle-of-gods","iron-bank","sealords-palace","purple-harbor","drowned-town"],sources:[{ref:"affc",checked:"memory",note:{en:"The Braavos chapters (arrival past the Titan and Arsenal, canals, harbours, the temple doors) recalled from memory, not re-read.",zh:"\u5E03\u62C9\u4F5B\u65AF\u76F8\u5173\u7AE0\u8282\uFF08\u9A76\u8FC7\u6CF0\u5766\u4E0E\u5175\u5DE5\u5382\u3001\u8FD0\u6CB3\u3001\u6E2F\u53E3\u3001\u795E\u6BBF\u5927\u95E8\uFF09\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF0C\u672A\u91CD\u8BFB\u539F\u6587\u3002"}},{ref:"adwd",checked:"memory",note:{en:"The Iron Bank's envoy travelling to Westeros recalled from memory; the bank's building is not described there.",zh:"\u94C1\u91D1\u5E93\u4F7F\u8005\u524D\u5F80\u7EF4\u65AF\u7279\u6D1B\u7684\u60C5\u8282\u51ED\u8BB0\u5FC6\u590D\u8FF0\uFF1B\u4E66\u4E2D\u672A\u63CF\u5199\u94C1\u91D1\u5E93\u7684\u5EFA\u7B51\u3002"}},{ref:"awoiaf",checked:"search-snippet",note:{en:"Arsenal on a fortified rock just past the Titan; Chequy Port on an island south-east of it where customs officers board ships; Ragman's Harbor (west, foreign ships) and Purple Harbor (north, Braavosi ships, near the Sealord's Palace): web-search summaries only, pages not fetched.",zh:"\u5175\u5DE5\u5382\u4F4D\u4E8E\u6CF0\u5766\u540E\u65B9\u4E00\u5904\u8BBE\u9632\u7684\u5CA9\u4E18\uFF1B\u65B9\u683C\u6E2F\u5728\u5176\u4E1C\u5357\u7684\u5C9B\u4E0A\uFF0C\u6D77\u5173\u5B98\u5458\u5728\u6B64\u767B\u8239\u67E5\u9A8C\uFF1B\u62C9\u683C\u66FC\u6E2F\uFF08\u57CE\u897F\uFF0C\u5916\u56FD\u8239\u53EA\uFF09\u4E0E\u7D2B\u6E2F\uFF08\u57CE\u5317\uFF0C\u672C\u5730\u8239\u53EA\uFF0C\u8FD1\u6D77\u738B\u5BAB\uFF09\uFF1A\u4EC5\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\uFF0C\u672A\u80FD\u6253\u5F00\u9875\u9762\u3002"}},{ref:"twoiaf",checked:"search-snippet",note:{en:"Rocky seaward islands sheltering the lagoon: web-search summary only.",zh:"\u5916\u6D77\u5CA9\u5C9B\u5C4F\u62A4\u6F5F\u6E56\u4E00\u8BF4\uFF1A\u4EC5\u636E\u7F51\u7EDC\u641C\u7D22\u6458\u8981\u3002"}}],landmarks:{titan:e({en:"The Titan",zh:"\u5E03\u62C9\u4F5B\u65AF\u6CF0\u5766"},{en:"A colossal warrior-fortress straddling the channel into the lagoon. Fires burn in its eyes, and it roars to announce arriving ships.",zh:"\u5DE8\u4EBA\u6218\u58EB\u6A21\u6837\u7684\u8981\u585E\uFF0C\u8DE8\u7ACB\u5728\u901A\u5F80\u6F5F\u6E56\u7684\u6C34\u9053\u4E4B\u4E0A\u3002\u53CC\u773C\u71C3\u7740\u706B\u7130\uFF0C\u6709\u8239\u9A76\u8FD1\u4FBF\u53D1\u51FA\u543C\u58F0\u3002"},{en:"Every ship enters between its legs, under its burning eyes.",zh:"\u6BCF\u8258\u8239\u90FD\u8981\u4ECE\u5B83\u80EF\u4E0B\u9A76\u8FC7\uFF0C\u5934\u9876\u662F\u71C3\u70E7\u7684\u53CC\u773C\u3002"},{confidence:"high",refs:["affc","twoiaf"],book:{en:"A giant fortress in the shape of a warrior guards the entrance; ships pass beneath it; its eyes burn and it gives a great roar.",zh:"\u5F62\u5982\u6218\u58EB\u7684\u5DE8\u578B\u8981\u585E\u627C\u5B88\u5165\u53E3\uFF0C\u8239\u53EA\u4ECE\u5176\u4E0B\u7A7F\u8FC7\uFF1B\u5B83\u53CC\u773C\u71C3\u706B\uFF0C\u5E76\u4F1A\u53D1\u51FA\u9707\u5929\u543C\u58F0\u3002"},unknown:{en:"Exact height, pose, materials and interior layout.",zh:"\u786E\u5207\u9AD8\u5EA6\u3001\u59FF\u6001\u3001\u6750\u8D28\u4E0E\u5185\u90E8\u683C\u5C40\u3002"},interpretation:{en:"Feet planted on two sea-stacks, a torso hall with windows and murder-holes, a sword at one foot, about 120 m tall.",zh:"\u53CC\u811A\u5206\u8E0F\u4E24\u5EA7\u6D77\u8680\u67F1\uFF0C\u8EAF\u5E72\u5185\u8BBE\u5E26\u7A97\u53E3\u4E0E\u6740\u4EBA\u5B54\u7684\u5385\u5BA4\uFF0C\u4E00\u4FA7\u811A\u8FB9\u7ACB\u5251\uFF0C\u9AD8\u7EA6120\u7C73\u3002"}}),arsenal:e({en:"The Arsenal",zh:"\u5175\u5DE5\u5382"},{en:"A fortified shipyard just inside the Titan, home of the Braavosi war fleet and famed for building a war galley in a single day.",zh:"\u7D27\u6328\u6CF0\u5766\u5185\u4FA7\u7684\u8BBE\u9632\u8239\u5382\uFF0C\u5E03\u62C9\u4F5B\u65AF\u6218\u8230\u961F\u7684\u6BCD\u6E2F\uFF0C\u4EE5\u4E00\u5929\u9020\u6210\u4E00\u8258\u6218\u8230\u95FB\u540D\u3002"},{en:"Behind the Titan, the Arsenal can build a war galley in a day.",zh:"\u6CF0\u5766\u8EAB\u540E\u7684\u5175\u5DE5\u5382\uFF0C\u4E00\u5929\u5C31\u80FD\u9020\u51FA\u4E00\u8258\u6218\u8230\u3002"},{confidence:"high",refs:["affc","awoiaf"],book:{en:"The Arsenal lies just beyond the Titan and is said to build a war galley in a day; a wiki summary adds stone battlements and siege engines.",zh:"\u5175\u5DE5\u5382\u7D27\u90BB\u6CF0\u5766\u4E4B\u540E\uFF0C\u636E\u8BF4\u4E00\u5929\u53EF\u9020\u4E00\u8258\u6218\u8230\uFF1B\u7EF4\u57FA\u6458\u8981\u53E6\u63D0\u5230\u77F3\u780C\u96C9\u581E\u4E0E\u5B88\u57CE\u5668\u68B0\u3002"},unknown:{en:"Its layout, sheds and gates.",zh:"\u5E03\u5C40\u3001\u8239\u68DA\u4E0E\u5927\u95E8\u3002"},interpretation:{en:"A walled island with galley sheds, a water-gate to the lagoon and a crane tower.",zh:"\u4E00\u5EA7\u56F4\u5899\u73AF\u7ED5\u7684\u5C9B\uFF0C\u5185\u6709\u8239\u68DA\u3001\u901A\u5F80\u6F5F\u6E56\u7684\u6C34\u95E8\u548C\u4E00\u5EA7\u540A\u81C2\u5854\u3002"}}),"chequy-port":e({en:"Chequy Port",zh:"\u65B9\u683C\u6E2F"},{en:"Where the Sealord's customs officers board arriving merchant ships to inspect their holds.",zh:"\u6D77\u738B\u7684\u6D77\u5173\u5B98\u5458\u5728\u6B64\u767B\u4E0A\u5165\u6E2F\u5546\u8239\uFF0C\u67E5\u9A8C\u8D27\u8231\u3002"},{en:"Merchant ships wait here, sometimes half a day, for inspection.",zh:"\u5546\u8239\u5728\u6B64\u5019\u68C0\uFF0C\u6709\u65F6\u4E00\u7B49\u5C31\u662F\u534A\u5929\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"Per a wiki summary citing A Feast for Crows: a harbour on an island south-east of the Arsenal where customs officers inspect cargo, which can take half a day.",zh:"\u636E\u63F4\u5F15\u300A\u7FA4\u9E26\u7684\u76DB\u5BB4\u300B\u7684\u7EF4\u57FA\u6458\u8981\uFF1A\u6E2F\u53E3\u4F4D\u4E8E\u5175\u5DE5\u5382\u4E1C\u5357\u7684\u5C9B\u4E0A\uFF0C\u6D77\u5173\u5728\u6B64\u67E5\u9A8C\u8D27\u7269\uFF0C\u8017\u65F6\u53EF\u8FBE\u534A\u5929\u3002"},unknown:{en:'Its appearance and why it is called "chequy".',zh:"\u5916\u89C2\uFF0C\u4EE5\u53CA\u201C\u65B9\u683C\u201D\u4E4B\u540D\u4ECE\u4F55\u800C\u6765\u3002"},interpretation:{en:"Chequered paving is this scene's own reading of the name.",zh:"\u65B9\u683C\u94FA\u5730\u662F\u672C\u573A\u666F\u5BF9\u540D\u79F0\u7684\u6F14\u7ECE\u3002"}}),"canals-and-bridges":e({en:"Canals and Bridges",zh:"\u8FD0\u6CB3\u4E0E\u6865\u6881"},{en:"Braavos has canals where other cities have streets; boats are the everyday way to travel, and bridges join the islands.",zh:"\u522B\u5904\u6709\u8857\u9053\uFF0C\u5E03\u62C9\u4F5B\u65AF\u6709\u8FD0\u6CB3\u3002\u65E5\u5E38\u51FA\u884C\u9760\u8239\uFF0C\u5C9B\u4E0E\u5C9B\u4E4B\u95F4\u4EE5\u6865\u76F8\u8FDE\u3002"},{en:"No streets here: the canals are the roads.",zh:"\u8FD9\u91CC\u6CA1\u6709\u8857\u9053\uFF0C\u8FD0\u6CB3\u5C31\u662F\u8DEF\u3002"},{confidence:"high",refs:["affc","twoiaf"],book:{en:"A city of about a hundred islands joined by bridges, with boats on the canals as the main way to get about.",zh:"\u7EA6\u767E\u5EA7\u5C9B\u5C7F\u4EE5\u6865\u76F8\u8FDE\uFF0C\u8FD0\u6CB3\u884C\u8239\u662F\u4E3B\u8981\u7684\u4EA4\u901A\u65B9\u5F0F\u3002"},unknown:{en:"Island shapes and the canal map.",zh:"\u5404\u5C9B\u5F62\u72B6\u4E0E\u8FD0\u6CB3\u5206\u5E03\u3002"},interpretation:{en:"A loose grid of islands around a wide central canal; bridge positions are arbitrary.",zh:"\u5C9B\u5C7F\u56F4\u7ED5\u4E00\u6761\u5BBD\u9614\u7684\u4E2D\u592E\u8FD0\u6CB3\u677E\u6563\u6392\u5E03\uFF1B\u6865\u7684\u4F4D\u7F6E\u968F\u610F\u5B89\u6392\u3002"}}),"ragmans-harbor":e({en:"Ragman's Harbor",zh:"\u62C9\u683C\u66FC\u6E2F"},{en:"The harbour for foreign ships: crowded, noisy and shabbier than the Braavosi docks.",zh:"\u5916\u56FD\u8239\u53EA\u505C\u6CCA\u7684\u6E2F\u53E3\uFF0C\u62E5\u6324\u55A7\u95F9\uFF0C\u8FDC\u4E0D\u5982\u672C\u57CE\u8239\u575E\u4F53\u9762\u3002"},{en:"Foreign ships tie up here, among shacks, gulls and smoke.",zh:"\u5916\u56FD\u8239\u5728\u6B64\u9760\u5CB8\uFF0C\u56DB\u5468\u662F\u68DA\u5C4B\u3001\u6D77\u9E25\u4E0E\u708A\u70DF\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"Ragman's Harbor is where foreign ships dock; a wiki summary puts it on the city's west side.",zh:"\u5916\u56FD\u8239\u53EA\u505C\u9760\u62C9\u683C\u66FC\u6E2F\uFF1B\u7EF4\u57FA\u6458\u8981\u79F0\u5176\u4F4D\u4E8E\u57CE\u897F\u3002"},unknown:{en:"Its size and exact shape.",zh:"\u89C4\u6A21\u4E0E\u786E\u5207\u5F62\u72B6\u3002"},interpretation:{en:"Long timber piers and a rough fringe of warehouses on the west edge.",zh:"\u897F\u7F18\u7684\u957F\u6728\u6808\u6865\u4E0E\u4E00\u6392\u7B80\u964B\u4ED3\u623F\u3002"}}),"house-black-white":e({en:"House of Black and White",zh:"\u9ED1\u767D\u4E4B\u9662"},{en:"A temple with two carved doors, one of pale weirwood and one of black ebony. What happens inside is secret, so no cutaway is shown.",zh:"\u795E\u6BBF\u6709\u4E24\u6247\u96D5\u82B1\u5927\u95E8\uFF0C\u4E00\u6247\u662F\u82CD\u767D\u7684\u9C7C\u6881\u6728\uFF0C\u4E00\u6247\u662F\u4E4C\u9ED1\u7684\u4E4C\u6728\u3002\u6BBF\u5185\u4E4B\u4E8B\u79D8\u4E0D\u793A\u4EBA\uFF0C\u6545\u4E0D\u4F5C\u5256\u9762\u3002"},{en:"One door white, one black. What lies within is not for visitors.",zh:"\u4E00\u95E8\u767D\uFF0C\u4E00\u95E8\u9ED1\u3002\u95E8\u540E\u4E4B\u4E8B\uFF0C\u5916\u4EBA\u4E0D\u5F97\u7AA5\u63A2\u3002"},{confidence:"high",refs:["affc"],book:{en:"The temple has two doors, one of weirwood and one of ebony, and is the house of the Faceless Men.",zh:"\u795E\u6BBF\u6709\u4E24\u6247\u95E8\uFF0C\u4E00\u6247\u9C7C\u6881\u6728\uFF0C\u4E00\u6247\u4E4C\u6728\uFF0C\u662F\u65E0\u9762\u8005\u7684\u5C45\u6240\u3002"},unknown:{en:"Its exact shape, its position in the city and its interior.",zh:"\u786E\u5207\u5F62\u5236\u3001\u5728\u57CE\u4E2D\u7684\u4F4D\u7F6E\u4E0E\u5185\u90E8\u60C5\u5F62\u3002"},interpretation:{en:"A half-white, half-black block on a small island; position and form are invented.",zh:"\u5C0F\u5C9B\u4E0A\u4E00\u5EA7\u534A\u767D\u534A\u9ED1\u7684\u65B9\u5F62\u5EFA\u7B51\uFF1B\u4F4D\u7F6E\u4E0E\u5F62\u5236\u5747\u4E3A\u81EA\u62DF\u3002"}}),"isle-of-gods":e({en:"Isle of the Gods",zh:"\u4F17\u795E\u4E4B\u5C9B"},{en:"An island crowded with temples to the many gods that Braavos tolerates.",zh:"\u5C9B\u4E0A\u795E\u6BBF\u6797\u7ACB\uFF0C\u4F9B\u5949\u5E03\u62C9\u4F5B\u65AF\u6240\u5BB9\u7EB3\u7684\u5404\u8DEF\u795E\u660E\u3002"},{en:"Braavos welcomes every faith; here their temples stand side by side.",zh:"\u5E03\u62C9\u4F5B\u65AF\u6765\u8005\u4E0D\u62D2\uFF0C\u8BF8\u795E\u7684\u6BBF\u5802\u5728\u6B64\u6BD4\u80A9\u800C\u7ACB\u3002"},{confidence:"medium",refs:["affc"],book:{en:"The novels name an Isle of the Gods with temples to many faiths; details were not re-checked.",zh:"\u5C0F\u8BF4\u63D0\u5230\u4F17\u795E\u4E4B\u5C9B\uFF0C\u5C9B\u4E0A\u6709\u591A\u79CD\u4FE1\u4EF0\u7684\u795E\u6BBF\uFF1B\u7EC6\u8282\u672A\u590D\u6838\u3002"},unknown:{en:"Which temples stand there, where, and how they look.",zh:"\u6709\u54EA\u4E9B\u795E\u6BBF\u3001\u4F4D\u7F6E\u4F55\u5728\u3001\u5916\u89C2\u5982\u4F55\u3002"},interpretation:{en:"Seven small temples with varied roofs among cypresses.",zh:"\u67CF\u6811\u95F4\u4E03\u5EA7\u5C4B\u9876\u5404\u5F02\u7684\u5C0F\u795E\u6BBF\u3002"}}),"iron-bank":e({en:"Iron Bank",zh:"\u94C1\u91D1\u5E93"},{en:"The great bank of Braavos; kings and cities borrow from it, and it always collects.",zh:"\u5E03\u62C9\u4F5B\u65AF\u7684\u5DE8\u5BCC\u94F6\u884C\u3002\u541B\u738B\u4E0E\u57CE\u90A6\u90FD\u5411\u5B83\u501F\u8D37\uFF0C\u800C\u5B83\u5411\u6765\u6709\u503A\u5FC5\u6536\u3002"},{en:"Kings borrow here. Few dare forget to repay.",zh:"\u541B\u738B\u5728\u6B64\u501F\u8D37\uFF0C\u5C11\u6709\u4EBA\u6562\u8D56\u8D26\u3002"},{confidence:"medium",refs:["asos","affc","adwd"],book:{en:"The Iron Bank of Braavos lends to rulers far and wide and is famous for collecting its debts.",zh:"\u5E03\u62C9\u4F5B\u65AF\u94C1\u91D1\u5E93\u653E\u8D37\u56DB\u65B9\uFF0C\u4EE5\u8BA8\u503A\u5FC5\u679C\u95FB\u540D\u3002"},unknown:{en:"The building's appearance and position.",zh:"\u5EFA\u7B51\u5916\u89C2\u4E0E\u4F4D\u7F6E\u3002"},interpretation:{en:"A grey, fortress-like block with narrow windows and iron doors; invented.",zh:"\u7A84\u7A97\u94C1\u95E8\u3001\u5F62\u4F3C\u5821\u5792\u7684\u7070\u8272\u697C\u5B87\uFF1B\u7CFB\u81EA\u62DF\u3002"}}),"sealords-palace":e({en:"Sealord's Palace",zh:"\u6D77\u738B\u5BAB"},{en:"Seat of the Sealord, Braavos's elected ruler; here imagined as a grand palace above the harbour.",zh:"\u6D77\u738B\u7684\u5C45\u6240\u3002\u6D77\u738B\u7ECF\u63A8\u9009\u4EA7\u751F\uFF0C\u7EDF\u6CBB\u5E03\u62C9\u4F5B\u65AF\uFF1B\u6B64\u5904\u8BBE\u60F3\u4E3A\u4FEF\u4E34\u6E2F\u53E3\u7684\u5B8F\u4F1F\u5BAB\u6BBF\u3002"},{en:"The Sealord holds court here, above the Purple Harbor.",zh:"\u6D77\u738B\u5728\u6B64\u4E34\u671D\uFF0C\u811A\u4E0B\u4FBF\u662F\u7D2B\u6E2F\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"Braavos is ruled by an elected Sealord from his palace; a wiki summary puts the Purple Harbor near it.",zh:"\u5E03\u62C9\u4F5B\u65AF\u7531\u63A8\u9009\u7684\u6D77\u738B\u5728\u5BAB\u4E2D\u7EDF\u6CBB\uFF1B\u7EF4\u57FA\u6458\u8981\u79F0\u7D2B\u6E2F\u5728\u5BAB\u6BBF\u9644\u8FD1\u3002"},unknown:{en:"Its architecture and exact site.",zh:"\u5EFA\u7B51\u6837\u5F0F\u4E0E\u786E\u5207\u4F4D\u7F6E\u3002"},interpretation:{en:"A pale marble hall with verdigris domes and an arcade facing the water.",zh:"\u6D45\u8272\u5927\u7406\u77F3\u6BBF\u5802\uFF0C\u94DC\u7EFF\u7A79\u9876\uFF0C\u4E34\u6C34\u8BBE\u62F1\u5ECA\u3002"}}),"purple-harbor":e({en:"Purple Harbor",zh:"\u7D2B\u6E2F"},{en:"The harbour reserved for Braavosi ships, on the north side of the city near the Sealord's Palace.",zh:"\u4E13\u4F9B\u5E03\u62C9\u4F5B\u65AF\u672C\u5730\u8239\u53EA\u505C\u6CCA\u7684\u6E2F\u53E3\uFF0C\u4F4D\u4E8E\u57CE\u5317\uFF0C\u90BB\u8FD1\u6D77\u738B\u5BAB\u3002"},{en:"Only Braavosi ships may moor in the Purple Harbor.",zh:"\u552F\u6709\u5E03\u62C9\u4F5B\u65AF\u7684\u8239\u53EF\u4EE5\u6CCA\u5165\u7D2B\u6E2F\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"Braavosi ships use the Purple Harbor; a wiki summary places it on the north side.",zh:"\u5E03\u62C9\u4F5B\u65AF\u8239\u53EA\u505C\u9760\u7D2B\u6E2F\uFF1B\u7EF4\u57FA\u6458\u8981\u79F0\u5176\u4F4D\u4E8E\u57CE\u5317\u3002"},unknown:{en:"Why it is called purple.",zh:"\u4E3A\u4F55\u4EE5\u201C\u7D2B\u201D\u4E3A\u540D\u3002"},interpretation:{en:"Violet sails and banners are this scene's colour reading of the name.",zh:"\u7D2B\u8272\u8239\u5E06\u4E0E\u65D7\u5E1C\u662F\u672C\u573A\u666F\u5BF9\u540D\u79F0\u7684\u914D\u8272\u6F14\u7ECE\u3002"}}),"drowned-town":e({en:"The Drowned Town",zh:"\u6C89\u6CA1\u9547"},{en:"An old quarter now largely under water; only towers and domes rise above the lagoon.",zh:"\u4E00\u7247\u53E4\u8001\u8857\u533A\uFF0C\u5982\u4ECA\u5927\u534A\u6CA1\u5165\u6C34\u4E2D\uFF0C\u53EA\u5269\u5854\u697C\u4E0E\u7A79\u9876\u63A2\u51FA\u6F5F\u6E56\u3002"},{en:"Half-sunken towers: Braavos slowly giving ground to the sea.",zh:"\u534A\u6C89\u7684\u5854\u697C\uFF1A\u5E03\u62C9\u4F5B\u65AF\u6B63\u4E00\u70B9\u70B9\u8BA9\u7ED9\u5927\u6D77\u3002"},{confidence:"medium",refs:["affc","awoiaf"],book:{en:"A largely submerged district with half-sunken towers and domes, per a wiki summary of the novels.",zh:"\u636E\u7EF4\u57FA\u5BF9\u5C0F\u8BF4\u7684\u6458\u8981\uFF0C\u8FD9\u662F\u4E00\u7247\u5927\u534A\u6DF9\u6CA1\u7684\u8857\u533A\uFF0C\u53EF\u89C1\u534A\u6C89\u7684\u5854\u697C\u4E0E\u7A79\u9876\u3002"},unknown:{en:"Its location and extent.",zh:"\u4F4D\u7F6E\u4E0E\u8303\u56F4\u3002"},interpretation:{en:"Placed in the south-east of the lagoon; the ruined shapes are invented.",zh:"\u7F6E\u4E8E\u6F5F\u6E56\u4E1C\u5357\uFF1B\u6B8B\u57A3\u9020\u578B\u4E3A\u81EA\u62DF\u3002"}}),"seaward-isles":e({en:"Seaward Isles",zh:"\u5916\u6D77\u5CA9\u5C9B"},{en:"Steep rocky islands on the seaward side shelter the lagoon from storms and enemies.",zh:"\u5916\u6D77\u4E00\u4FA7\u7684\u9661\u5CED\u5CA9\u5C9B\u4E3A\u6F5F\u6E56\u6321\u4F4F\u98CE\u6D6A\uFF0C\u4E5F\u6321\u4F4F\u6765\u654C\u3002"},{en:"Natural walls: cliffs and sea-stacks around the harbour mouth.",zh:"\u5929\u7136\u57CE\u5899\uFF1A\u6E2F\u53E3\u56DB\u5468\u7684\u5CED\u58C1\u4E0E\u6D77\u8680\u67F1\u3002"},{confidence:"low",refs:["twoiaf"],book:{en:"Only a search summary mentions rocky, mountainous islands shielding the lagoon.",zh:"\u4EC5\u6709\u641C\u7D22\u6458\u8981\u63D0\u53CA\u591A\u5C71\u7684\u5CA9\u5C9B\u5C4F\u62A4\u6F5F\u6E56\u3002"},unknown:{en:"Their number and layout.",zh:"\u6570\u91CF\u4E0E\u5206\u5E03\u3002"},interpretation:{en:"Several grey-green stacks around the entrance; positions are invented.",zh:"\u5165\u53E3\u5468\u56F4\u6570\u5EA7\u7070\u7EFF\u8272\u5CA9\u5C9B\uFF1B\u4F4D\u7F6E\u4E3A\u81EA\u62DF\u3002"}})}};export{t as default};
